BEGIN;
SELECT plan(40);

SELECT has_table('public', 'schedule_template_breaks', 'planned breaks are linked to schedule days');
SELECT has_column('public', 'schedule_templates', 'workday_type', 'shift classification is configurable');
SELECT has_column('public', 'schedule_templates', 'entry_tolerance_minutes', 'entry tolerance is configurable');
SELECT has_column('public', 'schedule_templates', 'effective_from', 'schedule versions have an effective start');
SELECT has_column('public', 'schedule_templates', 'revision_of', 'schedule revisions retain their predecessor');
SELECT has_column('public', 'break_rules', 'requires_qr', 'break QR requirement is configurable');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.schedule_template_breaks'::regclass), 'planned breaks require RLS');
SELECT ok(EXISTS (SELECT 1 FROM pg_policy WHERE polrelid='public.schedule_template_breaks'::regclass AND polname='schedule_template_breaks_read' AND polcmd='r'), 'breaks have a tenant read policy');
SELECT ok(EXISTS (SELECT 1 FROM pg_policy WHERE polrelid='public.schedule_template_breaks'::regclass AND polname='schedule_template_breaks_insert' AND polcmd='a'), 'break writes require the schedule permission');
SELECT ok(EXISTS (SELECT 1 FROM pg_policy WHERE polrelid='public.schedule_template_breaks'::regclass AND polname='schedule_template_breaks_update' AND polcmd='w'), 'break updates require the schedule permission');
SELECT ok(EXISTS (SELECT 1 FROM pg_policy WHERE polrelid='public.schedule_template_breaks'::regclass AND polname='schedule_template_breaks_delete' AND polcmd='d'), 'break deletion requires the schedule permission');
SELECT ok(has_function_privilege('authenticated', 'public.assign_employee_schedule(uuid,uuid[],uuid,uuid,date,date)', 'EXECUTE'), 'authenticated admins can create assignments through the transaction');
SELECT ok(has_function_privilege('authenticated', 'public.save_schedule_template(uuid,uuid,text,public.schedule_kind,text,smallint,date,date,jsonb,uuid)', 'EXECUTE'), 'authenticated admins can save versioned templates');
SELECT ok(NOT (SELECT prosecdef FROM pg_proc WHERE oid='public.assign_employee_schedule(uuid,uuid[],uuid,uuid,date,date)'::regprocedure), 'assignment RPC uses caller privileges and RLS');
SELECT ok(NOT (SELECT prosecdef FROM pg_proc WHERE oid='public.save_schedule_template(uuid,uuid,text,public.schedule_kind,text,smallint,date,date,jsonb,uuid)'::regprocedure), 'template RPC uses caller privileges and RLS');
SELECT ok(position('schedule assignment overlaps an existing period' in pg_get_functiondef('private.guard_schedule_assignment_overlap()'::regprocedure)) > 0, 'assignment trigger rejects overlapping periods');
SELECT ok(EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.schedule_assignments'::regclass AND tgname='schedule_assignments_no_overlap' AND NOT tgisinternal), 'assignment overlap trigger is installed');
SELECT ok(EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid='public.schedule_template_days'::regclass AND tgname='schedule_template_days_immutable_after_assignment' AND NOT tgisinternal), 'assigned schedule days cannot be edited in place');
SELECT ok(position('pg_advisory_xact_lock' in pg_get_functiondef('private.guard_labor_rule_period_overlap()'::regprocedure)) > 0, 'labor-rule validity changes are serialized');
SELECT ok(position('extract(isodow from local.local_day)' in pg_get_functiondef('private.record_attendance_event(uuid,text,text,public.attendance_event_type,uuid,uuid)'::regprocedure)) > 0, 'attendance snapshots use the local weekday schedule');
SELECT is(((timestamp '2026-01-01 22:00' at time zone 'America/Mexico_City') + interval '8 hours'), (timestamp '2026-01-02 06:00' at time zone 'America/Mexico_City'), 'overnight schedule end resolves on the next local date');
SELECT is((480 - 60)::integer, 420, 'a non-computable planned break is excluded from scheduled work');
SELECT is((480 - 0)::integer, 480, 'a computable planned break remains part of scheduled work');
SELECT ok(position('detected_overtime_minutes' in pg_get_viewdef('public.attendance_session_totals'::regclass)) > 0 AND to_regclass('public.overtime_authorizations') IS NOT NULL, 'detected and authorized overtime remain separate');
SELECT ok(to_regprocedure('private.can_manage_branch(uuid,uuid,text)') IS NOT NULL, 'branch writes have an explicit permission-and-membership guard');
SELECT ok((SELECT position('can_manage_branch' in pg_get_expr(polwithcheck,polrelid)) > 0 FROM pg_policy WHERE polrelid='public.schedule_templates'::regclass AND polname='schedule_templates_manage'), 'schedule template writes require schedule permission and branch scope');
SELECT ok((SELECT position('can_manage_branch' in pg_get_expr(polwithcheck,polrelid)) > 0 FROM pg_policy WHERE polrelid='public.attendance_adjustments'::regclass AND polname='attendance_adjustments_submit'), 'attendance corrections require permission and session branch scope');
SELECT ok((SELECT prosecdef AND 'search_path=""'=ANY(proconfig) FROM pg_proc WHERE oid='private.can_manage_branch(uuid,uuid,text)'::regprocedure), 'branch permission guard is SECURITY DEFINER with an empty search_path');
SELECT ok(has_function_privilege('authenticated','private.can_manage_branch(uuid,uuid,text)','EXECUTE') AND NOT has_function_privilege('anon','private.can_manage_branch(uuid,uuid,text)','EXECUTE'), 'only authenticated clients can invoke the branch permission guard');
SELECT is((SELECT count(*)::integer FROM pg_policy WHERE polrelid IN ('public.schedule_templates'::regclass,'public.schedule_template_days'::regclass,'public.schedule_assignments'::regclass,'public.schedule_template_breaks'::regclass,'public.attendance_adjustments'::regclass) AND polpermissive AND polcmd IN ('*','a','w','d')), 7, 'schedule and correction tables have only the expected permissive write policies');
SELECT ok(NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid IN ('public.schedule_templates'::regclass,'public.schedule_template_days'::regclass,'public.schedule_assignments'::regclass,'public.schedule_template_breaks'::regclass,'public.attendance_adjustments'::regclass) AND polpermissive AND polcmd IN ('*','a','w','d') AND (coalesce(pg_get_expr(polqual,polrelid),'') || coalesce(pg_get_expr(polwithcheck,polrelid),'')) NOT LIKE '%can_manage_branch%'), 'every permissive schedule/correction write policy delegates to the permission-and-branch guard');

SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.labor_rule_sets'::regclass), 'labor rules require RLS');
SELECT ok((SELECT relrowsecurity FROM pg_class WHERE oid='public.overtime_authorizations'::regclass), 'overtime authorizations require RLS');
SELECT is((SELECT count(*)::integer FROM pg_policy WHERE polrelid='public.labor_rule_sets'::regclass AND polpermissive AND polcmd IN ('*','a','w','d')), 1, 'labor rules have exactly one permissive write policy');
SELECT ok((SELECT polname='labor_rules_manage' AND polcmd='*' AND position('company.manage' in pg_get_expr(polqual,polrelid))>0 AND position('company.manage' in pg_get_expr(polwithcheck,polrelid))>0 FROM pg_policy WHERE polrelid='public.labor_rule_sets'::regclass AND polpermissive AND polcmd IN ('*','a','w','d')), 'all labor-rule writes require company.manage in USING and WITH CHECK');
SELECT is((SELECT count(*)::integer FROM pg_policy WHERE polrelid='public.overtime_authorizations'::regclass AND polpermissive AND polcmd IN ('*','a','w','d')), 1, 'overtime authorizations have exactly one permissive write policy');
SELECT ok((SELECT polname='overtime_authorizations_manage' AND polcmd='*' AND position('overtime.manage' in pg_get_expr(polqual,polrelid))>0 AND position('overtime.manage' in pg_get_expr(polwithcheck,polrelid))>0 FROM pg_policy WHERE polrelid='public.overtime_authorizations'::regclass AND polpermissive AND polcmd IN ('*','a','w','d')), 'all overtime authorization writes require overtime.manage in USING and WITH CHECK');
SELECT ok(EXISTS (SELECT 1 FROM pg_policy WHERE polrelid='public.overtime_authorizations'::regclass AND polname='employee_own_overtime_authorizations_read' AND polcmd='r') AND NOT EXISTS (SELECT 1 FROM pg_policy WHERE polrelid='public.overtime_authorizations'::regclass AND polname='employee_own_overtime_authorizations_read' AND polcmd<>'r'), 'employee overtime policy is read-only and does not add a write path');
SELECT ok(NOT has_table_privilege('authenticated','public.labor_rule_sets','DELETE'), 'direct labor-rule DELETE privilege stays revoked in favor of guarded RPC');
SELECT ok((SELECT prosecdef AND 'search_path=""'=ANY(proconfig) AND position('company.manage' in pg_get_functiondef(oid))>0 AND position('overtime_assessments' in pg_get_functiondef(oid))>0 FROM pg_proc WHERE oid='public.delete_labor_rule_set(uuid,uuid)'::regprocedure), 'labor-rule deletion RPC is isolated and checks authorization history');

SELECT * FROM finish();
ROLLBACK;
